sql:
SELECT GSoffered 
FROM schools 
WHERE ABS(Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools);

SELECT (SUM(CASE WHEN publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END)) AS difference
FROM superhero
JOIN publisher ON superhero.publisher_id = publisher.id;

SELECT team_short_name
FROM Team_Attributes
WHERE buildUpPlayPassing > 70;

SELECT CAST(SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(event_id)
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT expense_description
FROM expense
WHERE (SUM(cost) / COUNT(expense_id)) > 50;

SELECT CAST(SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) AS FLOAT) * 100.0 / COUNT(*) 
FROM gasstations 
WHERE Country = 'SVK';
